from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.shortcuts import get_object_or_404
from django_fsm import can_proceed
from .models import InsuranceClaim

class ClaimTransitionDispatcher(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, claim_id):
        action_name = request.data.get('action')
        claim = get_object_or_404(InsuranceClaim, id=claim_id, carrier=request.user.carrier)

        transition_fn = getattr(claim, action_name, None)
        if not transition_fn or not callable(transition_fn):
            return Response({'error': f'Invalid action {action_name}'}, status=status.HTTP_400_BAD_REQUEST)

        if not can_proceed(transition_fn):
            return Response({'error': 'Transition conditions not met'}, status=status.HTTP_400_BAD_REQUEST)

        transition_fn(performed_by=request.user)
        claim.save()
        return Response({'status': 'transitioned', 'new_state': claim.status})
